<?php require_once __DIR__.'/config.php'; require_login();if(!fams_current_type_allows('AICS','view_records')){http_response_code(403);exit('Your user type does not have permission for this action. Contact the Site Administrator if this access is required.');} $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT r.*,o.name office_name FROM aics_assistance_records r LEFT JOIN aics_offices o ON o.id=r.office_id WHERE r.id=?');$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('Record not found.');} // Read-only record viewing is available to all authorized AICS users across SWAD offices. Edit and status permissions remain office-scoped. ?><!doctype html><html lang="en"><head><meta charset="utf-8"><title><?=e($r['control_number'])?> | Print</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#163a5d;font-size:11px}.head{display:flex;align-items:center;border-bottom:3px solid #0b4d92;padding-bottom:10px;margin-bottom:16px}.head img{width:70px;height:70px;object-fit:contain;margin-right:14px}.head h1{font-size:18px;margin:0}.head p{margin:4px 0;color:#6d8091}.title{display:flex;justify-content:space-between}.control{font-size:18px;font-weight:800}.grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #d9e3ea}.cell{padding:8px 10px;border-right:1px solid #d9e3ea;border-bottom:1px solid #d9e3ea}.label{font-size:8px;text-transform:uppercase;color:#7b8d9d;font-weight:700;margin-bottom:3px}.value{font-weight:700}.full{grid-column:1/3}.section{font-size:11px;font-weight:800;background:#eef5fa;padding:8px;margin-top:14px}.sign{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-top:70px}.sig{border-top:1px solid #7890a2;text-align:center;padding-top:6px}.print{position:fixed;right:20px;top:20px;padding:8px 12px;background:#0b4d92;color:#fff;border:0;border-radius:6px}@media print{.print{display:none}}</style></head><body><button class="print" onclick="window.print()">Print</button><div class="head"><img src="assets/branding/dswd-region2-sticker.png"><div><h1>Financial Assistance Monitoring System</h1><p>DSWD • SWAD Region II • Centralized Masterlist</p></div></div><div class="title"><div><div class="control"><?=e($r['control_number'])?></div><div><?=e($r['office_name']??'Unassigned')?></div></div><div><strong><?=e($r['status'])?></strong></div></div><div class="section">SUBMISSION & ASSISTANCE</div><div class="grid"><div class="cell"><div class="label">Date of Submission</div><div class="value"><?=e($r['date_submission'])?></div></div><div class="cell"><div class="label">Assistance Type</div><div class="value"><?=e($r['assistance_type'])?></div></div><div class="cell"><div class="label">Guarantee Amount</div><div class="value"><?=money((float)$r['guarantee_amount'])?></div></div><div class="cell"><div class="label">Validity</div><div class="value"><?=e($r['validity_status'])?></div></div></div><div class="section">CLIENT</div><div class="grid"><div class="cell full"><div class="label">Name</div><div class="value"><?=e(record_client_name($r))?></div></div><div class="cell"><div class="label">Contact</div><div class="value"><?=e($r['contact_number']??'')?></div></div><div class="cell"><div class="label">Email</div><div class="value"><?=e($r['email']??'')?></div></div><div class="cell full"><div class="label">Address</div><div class="value"><?=e($r['barangay'].', '.$r['municipality'].', '.$r['province'])?></div></div></div><div class="section">BENEFICIARY</div><div class="grid"><div class="cell full"><div class="label">Name</div><div class="value"><?=e(record_beneficiary_name($r))?></div></div></div><div class="section">REMARKS</div><div class="grid"><div class="cell full"><?=nl2br(e($r['remarks']??''))?></div></div><div class="sign"><div class="sig">Prepared / Encoded By</div><div class="sig">Verified / Processed By</div></div></body></html>